        arr[i] = i; // store index
    }
    Arrays.sort(arr, (o1, o2) -> b[o1] - b[o2]);
    long ans = 0;
    for (int i = 0; i < n; i++) {
        int t = arr[i];
        int l = 0, r = i - 1, mid, ind = i;
        while (l <= r) {
            mid = l + (r - l) / 2;
            if (b[arr[mid]] >= a[t]) { // corrected line
                ind = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        ans += (i - ind);
    }
